CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, password_hash TEXT NOT NULL, admin INTEGER NOT NULL DEFAULT 0 CHECK(admin IN(0,1)));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE projects(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, manager_id INTEGER NOT NULL REFERENCES users(id), department TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','closed')), activities TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'), demo INTEGER NOT NULL DEFAULT 0, CHECK(start_date<=end_date));
CREATE TABLE memberships(project_id INTEGER NOT NULL REFERENCES projects(id), user_id INTEGER NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN('requester','manager','finance','viewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE approval_rules(kind TEXT PRIMARY KEY CHECK(kind IN('budget','spending')), rules TEXT NOT NULL);
CREATE TABLE budget_versions(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), version INTEGER NOT NULL, previous_id INTEGER REFERENCES budget_versions(id), reason TEXT NOT NULL, creator_id INTEGER NOT NULL REFERENCES users(id), state TEXT NOT NULL DEFAULT 'submitted' CHECK(state IN('submitted','approved')), approval_policy TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id,version));
CREATE TABLE budget_lines(id INTEGER PRIMARY KEY, budget_id INTEGER NOT NULL REFERENCES budget_versions(id), category TEXT NOT NULL, activity TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0 AND amount<=1000000000000), CHECK(start_date<=end_date));
CREATE TABLE funding_sources(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN('organization','donor')), categories TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, UNIQUE(project_id,name), CHECK(start_date<=end_date));
CREATE TABLE promises(id INTEGER PRIMARY KEY, source_id INTEGER NOT NULL REFERENCES funding_sources(id), amount INTEGER NOT NULL CHECK(amount>0), reference TEXT NOT NULL UNIQUE, date TEXT NOT NULL);
CREATE TABLE requests(id INTEGER PRIMARY KEY, title TEXT NOT NULL, creator_id INTEGER NOT NULL REFERENCES users(id), date TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'submitted' CHECK(state IN('submitted','approved','cancelled')), approval_policy TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE request_lines(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES requests(id), project_id INTEGER NOT NULL REFERENCES projects(id), source_id INTEGER NOT NULL REFERENCES funding_sources(id), category TEXT NOT NULL, activity TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0 AND amount<=1000000000000));
CREATE TABLE approvals(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, document_id INTEGER NOT NULL, revision INTEGER NOT NULL, level INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(kind,document_id,revision,level));
CREATE TABLE purchase_orders(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL UNIQUE REFERENCES requests(id), supplier TEXT NOT NULL, reference TEXT NOT NULL UNIQUE, date TEXT NOT NULL, created_by INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE accounts(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN('bank','cash','mobile','expense','asset','payable','advance','funding')));
CREATE TABLE periods(id INTEGER PRIMARY KEY, start_date TEXT NOT NULL, end_date TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('open','closed')), CHECK(start_date<=end_date));
CREATE TABLE journals(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, reference TEXT NOT NULL UNIQUE, date TEXT NOT NULL, description TEXT NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN('draft','posted')), reversal_of INTEGER UNIQUE REFERENCES journals(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE journal_lines(id INTEGER PRIMARY KEY, journal_id INTEGER NOT NULL REFERENCES journals(id), account_id INTEGER NOT NULL REFERENCES accounts(id), project_id INTEGER NOT NULL REFERENCES projects(id), source_id INTEGER NOT NULL REFERENCES funding_sources(id), amount INTEGER NOT NULL CHECK(amount<>0 AND abs(amount)<=1000000000000));
CREATE TABLE commitments(id INTEGER PRIMARY KEY, request_line_id INTEGER NOT NULL REFERENCES request_lines(id), amount INTEGER NOT NULL CHECK(amount<>0), journal_id INTEGER REFERENCES journals(id), reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE budget_charges(id INTEGER PRIMARY KEY, request_line_id INTEGER NOT NULL REFERENCES request_lines(id), amount INTEGER NOT NULL CHECK(amount<>0), journal_id INTEGER NOT NULL REFERENCES journals(id), date TEXT NOT NULL);
CREATE TABLE bills(id INTEGER PRIMARY KEY, po_id INTEGER NOT NULL REFERENCES purchase_orders(id), supplier TEXT NOT NULL, invoice TEXT NOT NULL, journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id), date TEXT NOT NULL, UNIQUE(supplier,invoice));
CREATE TABLE bill_lines(id INTEGER PRIMARY KEY, bill_id INTEGER NOT NULL REFERENCES bills(id), request_line_id INTEGER NOT NULL REFERENCES request_lines(id), amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE payments(id INTEGER PRIMARY KEY, bill_id INTEGER NOT NULL REFERENCES bills(id), journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id), account_id INTEGER NOT NULL REFERENCES accounts(id), reference TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), UNIQUE(account_id,reference));
CREATE TABLE advances(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL UNIQUE REFERENCES requests(id), beneficiary TEXT NOT NULL, journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id));
CREATE TABLE advance_lines(id INTEGER PRIMARY KEY, advance_id INTEGER NOT NULL REFERENCES advances(id), request_line_id INTEGER NOT NULL REFERENCES request_lines(id), amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE settlements(id INTEGER PRIMARY KEY, advance_id INTEGER NOT NULL REFERENCES advances(id), request_line_id INTEGER NOT NULL REFERENCES request_lines(id), amount INTEGER NOT NULL CHECK(amount>0), kind TEXT NOT NULL CHECK(kind IN('settlement','return')), journal_id INTEGER NOT NULL REFERENCES journals(id), evidence TEXT NOT NULL);
CREATE TABLE exceptions(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), amount INTEGER NOT NULL CHECK(amount>0), expiry TEXT NOT NULL, reason TEXT NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reconciliations(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), date TEXT NOT NULL, statement_balance INTEGER NOT NULL, outstanding TEXT NOT NULL, difference INTEGER NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE operations(user_id INTEGER NOT NULL REFERENCES users(id), key TEXT NOT NULL, payload_hash TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(user_id,key));
CREATE TABLE audit(id INTEGER PRIMARY KEY, actor_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX journal_dimensions ON journal_lines(project_id,source_id,account_id);
CREATE INDEX request_project ON request_lines(project_id,request_id);
CREATE INDEX charge_allocation ON budget_charges(request_line_id);
CREATE INDEX commitment_allocation ON commitments(request_line_id);
CREATE TRIGGER balanced_post BEFORE UPDATE OF state ON journals WHEN NEW.state='posted' AND (COALESCE((SELECT SUM(amount) FROM journal_lines WHERE journal_id=NEW.id),1)<>0 OR (SELECT COUNT(*) FROM journal_lines WHERE journal_id=NEW.id)<2) BEGIN SELECT RAISE(ABORT,'Journal must balance'); END;
CREATE TRIGGER journal_no_update BEFORE UPDATE ON journals WHEN OLD.state='posted' BEGIN SELECT RAISE(ABORT,'Posted journal is immutable'); END;
CREATE TRIGGER journal_no_delete BEFORE DELETE ON journals BEGIN SELECT RAISE(ABORT,'Journal cannot be deleted'); END;
CREATE TRIGGER lines_no_update BEFORE UPDATE ON journal_lines WHEN (SELECT state FROM journals WHERE id=OLD.journal_id)='posted' BEGIN SELECT RAISE(ABORT,'Posted journal lines are immutable'); END;
CREATE TRIGGER lines_no_delete BEFORE DELETE ON journal_lines WHEN (SELECT state FROM journals WHERE id=OLD.journal_id)='posted' BEGIN SELECT RAISE(ABORT,'Posted journal lines are immutable'); END;
CREATE TRIGGER lines_no_insert BEFORE INSERT ON journal_lines WHEN (SELECT state FROM journals WHERE id=NEW.journal_id)='posted' BEGIN SELECT RAISE(ABORT,'Posted journal lines are immutable'); END;
CREATE TRIGGER budget_no_update BEFORE UPDATE ON budget_versions WHEN OLD.state='approved' BEGIN SELECT RAISE(ABORT,'Approved budget is immutable'); END;
CREATE TRIGGER budget_no_delete BEFORE DELETE ON budget_versions BEGIN SELECT RAISE(ABORT,'Budget history is immutable'); END;
CREATE TRIGGER budget_line_no_update BEFORE UPDATE ON budget_lines BEGIN SELECT RAISE(ABORT,'Submit a new budget version'); END;
CREATE TRIGGER budget_line_no_delete BEFORE DELETE ON budget_lines BEGIN SELECT RAISE(ABORT,'Budget lines are immutable'); END;
CREATE TRIGGER budget_line_no_insert BEFORE INSERT ON budget_lines WHEN (SELECT state FROM budget_versions WHERE id=NEW.budget_id)='approved' BEGIN SELECT RAISE(ABORT,'Approved budget is immutable'); END;
CREATE TRIGGER request_line_no_update BEFORE UPDATE ON request_lines WHEN (SELECT state FROM requests WHERE id=OLD.request_id)<>'submitted' BEGIN SELECT RAISE(ABORT,'Approved allocation is immutable'); END;
CREATE TRIGGER request_line_no_delete BEFORE DELETE ON request_lines BEGIN SELECT RAISE(ABORT,'Allocation history is immutable'); END;
CREATE TRIGGER request_line_no_insert BEFORE INSERT ON request_lines WHEN (SELECT state FROM requests WHERE id=NEW.request_id)<>'submitted' BEGIN SELECT RAISE(ABORT,'Approved allocation is immutable'); END;
